#include "SampleIndex.h"
void SampleIndex::scan(const juce::Array<juce::File>&roots,int max){items.clear();const juce::StringArray ex={"wav","aif","aiff","flac","mp3","ogg","m4a"};for(const auto&r:roots){if(!r.isDirectory())continue;juce::DirectoryIterator it(r,true,"*",juce::File::findFiles);while(it.next()&&items.size()<max){auto f=it.getFile();auto e=f.getFileExtension().trimCharactersAtStart(".").toLowerCase();if(!ex.contains(e))continue;Item x;x.name=f.getFileNameWithoutExtension();x.path=f.getFullPathName();x.extension=e;x.size=f.getSize();x.id=juce::String::toHexString((juce::int64)f.getLastModificationTime().toMilliseconds())+"_"+juce::String::toHexString((juce::int64)f.getSize());items.add(x);}}}
juce::Array<SampleIndex::Item> SampleIndex::search(const juce::String&q,int max)const{auto ts=juce::StringArray::fromTokens(q.toLowerCase()," ","");juce::Array<Item>o;for(const auto&x:items){auto h=(x.name+" "+x.path).toLowerCase();bool ok=true;for(const auto&t:ts)if(t.isNotEmpty()&&!h.contains(t)){ok=false;break;}if(ok){o.add(x);if(o.size()>=max)break;}}return o;}
